<?php

namespace App\Data;

use Illuminate\Http\Request;
use Spatie\LaravelData\Data;
use Spatie\TypeScriptTransformer\Attributes\TypeScript;

/**
 * Props shared with every Inertia page. This class is the single source of truth:
 * the TypeScript counterpart is generated by `php artisan typescript:transform`
 * and registered as `sharedPageProps` in resources/js/types/inertia.d.ts.
 */
#[TypeScript]
class SharedData extends Data
{
    public function __construct(
        public string $name,
        public AuthData $auth,
        public bool $sidebarOpen,
        public string $theme,
        public FlashData $flash,
    ) {}

    public static function fromRequest(Request $request): self
    {
        $user = $request->user();

        return new self(
            name: config('app.name'),
            auth: new AuthData($user ? AuthUserData::fromUser($user) : null),
            sidebarOpen: $request->cookie('sidebar_state', 'true') === 'true',
            theme: $user?->settings?->theme ?? 'system',
            flash: FlashData::fromRequest($request),
        );
    }
}
